mapper.select:
SELECT c.id, c.discount_type, c.`specific`, c.discount_value, c.threshold_amount,
c.max_discount_amount,  uc.id AS creater
FROM user_coupon uc
INNER JOIN coupon c on uc.coupon_id = c.id
WHERE uc.id IN

    #{id}

AND uc.status = #{status}
AND uc.user_id = #{userId}

    AND uc.term_begin_time <= NOW() AND uc.term_end_time > NOW()
    AND (uc.reserved_order_id IS NULL OR uc.reserved_order_id = #{orderId})
